// =====================================================================
// 🎨 ბრენდის პროფილები (BRAND VOICE)
// ---------------------------------------------------------------------
// • ახალი კლიენტისთვის დააკოპირე ერთი ბლოკი და შეცვალე გასაღები/ველები.
// • Telegram-ში შეტყობინების ან ფაილის caption-ის დასაწყისში დაწერე
//   #გასაღები (მაგ.: #cafe), რომ ამ კლიენტის ტონი გამოიყენოს.
// • ჰეშთეგის გარეშე გამოიყენება DEFAULT_BRAND.
// • გასაღები: მხოლოდ ლათინური ასოები, ციფრები და _
// • vocabulary: კლიენტის ტერმინები მძიმით — ტრანსკრიფცია მათ სწორად ამოიცნობს
// =====================================================================
const DEFAULT_BRAND = 'default';

const BRANDS = {
  default: {
    client_name: 'სააგენტოს კლიენტი',
    brand_voice: 'მეგობრული, თანამედროვე და თავდაჯერებული. ვწერთ მარტივად და კონკრეტულად, ზედმეტი პათოსისა და კლიშეების გარეშე. იუმორი — მსუბუქად და ადგილზე. ემოჯი — ზომიერად.',
    target_audience: '25–45 წლის აქტიური ადამიანები, რომლებიც სოციალურ ქსელებში სასარგებლო და პრაქტიკულ ინფორმაციას ეძებენ.',
    address_form: 'შენობით (შენ)',
    cta: 'მოგვწერე პირად შეტყობინებაში',
    rules: 'არ გამოიყენო ფრაზები: „უნიკალური შესაძლებლობა“, „არ გამოტოვო“, „საუკეთესო ხარისხი“.',
    // ლექსიკონი: ბრენდის/პროდუქტის სახელები და ტერმინები — ეხმარება ტრანსკრიფციასაც და AI-საც
    vocabulary: '',
  },

  cafe: {
    client_name: 'ყავახანა (მაგალითი)',
    brand_voice: 'თბილი, მყუდრო, ოდნავ პოეტური. ვსაუბრობთ როგორც კარგი მეგობარი, რომელსაც ყავა უყვარს. ბევრი სენსორული დეტალი — არომატი, გემო, სინათლე.',
    target_audience: '20–35 წლის სტუდენტები, ფრილანსერები და ახალგაზრდა პროფესიონალები.',
    address_form: 'შენობით (შენ)',
    cta: 'შემოგვიარე — ყავა უკვე გელოდება',
    rules: 'ფასები და მენიუს პოზიციები მხოლოდ წყაროდან აიღე.',
    vocabulary: 'ესპრესო, კაპუჩინო, ფლეტ უაითი, ლატე, ფილტრ-ყავა, ქოლდ ბრიუ, მატჩა, ფუნთუშა, კრუასანი, სეზონური მენიუ, ბარისტა',
  },

  law: {
    client_name: 'იურიდიული ფირმა (მაგალითი)',
    brand_voice: 'ექსპერტული, დამაჯერებელი და მშვიდი. რთულ თემებს ვხსნით მარტივად, ჟარგონის გარეშე. იუმორი და ემოჯი — არა.',
    target_audience: 'მცირე და საშუალო ბიზნესის მფლობელები, დირექტორები, HR მენეჯერები.',
    address_form: 'თქვენობით (თქვენ)',
    cta: 'დაჯავშნეთ კონსულტაცია — ბმული პროფილშია',
    rules: 'არ გასცე კონკრეტული იურიდიული რჩევა; აღნიშნე, რომ ყველა შემთხვევა ინდივიდუალურია.',
    vocabulary: 'შრომის კოდექსი, შრომითი ხელშეკრულება, ანაზღაურებადი შვებულება, ანაზღაურებადი შვებულების დღეები, გამოსაცდელი ვადა, ზეგანაკვეთური სამუშაო, დამსაქმებელი, დასაქმებული, ხელფასი, ხელშეკრულების შეწყვეტა, კომპენსაცია',
  },
};

// --- ქვემოთ შეცვლა არ არის საჭირო ---
const msg = $('Telegram Trigger').first().json.message || {};
const raw = String(msg.text ?? msg.caption ?? '').trim();
const m = raw.match(/^#([a-z0-9_]+)/i);
const requested = m ? m[1].toLowerCase() : null;
const found = Boolean(requested && BRANDS[requested]);
const key = found ? requested : DEFAULT_BRAND;

return [{
  json: {
    brand_key: key,
    brand_tag: found ? m[0] : '',
    available_brands: Object.keys(BRANDS).map(k => '#' + k).join(', '),
    ...BRANDS[key],
  },
}];

// შემოსული შეტყობინების ტიპის დადგენა: media | url | text
// (ან შეცდომა: forbidden | help | too_large | unsupported_url | too_short | unsupported)
const s = $('Settings').first().json;
const brand = $('Brand Profiles').first().json;
const msg = $('Telegram Trigger').first().json.message || {};

const out = {
  ok: false,
  chat_id: msg.chat?.id,
  message_id: msg.message_id,
  user: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || '',
  type: '',
  source_type: '',
  source_ref: '',
  text: '',
  extra_context: '',
  url: '',
  file_id: '',
  error_message: '',
};
const fail = (type, message) => {
  out.type = type;
  out.error_message = message;
  return [{ json: out }];
};

// 1) წვდომის კონტროლი (Settings → allowed_chat_ids; ცარიელი = ყველას შეუძლია)
const allowed = String(s.allowed_chat_ids || '').split(',').map(x => x.trim()).filter(Boolean);
if (allowed.length && !allowed.includes(String(out.chat_id))) {
  return fail('forbidden', `⛔ ამ ბოტის გამოყენების უფლება არ გაქვს.\nშენი Chat ID: ${out.chat_id}\nგადაეცი ადმინისტრატორს, რომ სიაში დაგამატოს.`);
}

// 2) ტექსტი ან caption (ბრენდის #ტეგი იჭრება)
let raw = String(msg.text ?? msg.caption ?? '').trim();
if (brand.brand_tag && raw.startsWith(brand.brand_tag)) raw = raw.slice(brand.brand_tag.length).trim();

// 3) ბრძანებები
if (/^\/(start|help)\b/i.test(raw)) {
  return fail('help', [
    '👋 გამარჯობა! ერთი წყაროდან ვამზადებ სოციალური ქსელების კონტენტ-პაკეტს:',
    'Instagram, Facebook, LinkedIn, 3 Reels/TikTok იდეა და 5 სათაური.',
    '',
    'გამომიგზავნე:',
    '• ვიდეო, ვიდეო-რგოლი, ხმოვანი შეტყობინება ან აუდიო (მაქს. 20 MB)',
    '• სტატიის ლინკი',
    '• სტატიის ტექსტი ან ბრენდის მოკლე შეტყობინება',
    '',
    `კლიენტის ასარჩევად დასაწყისში დაწერე მისი ტეგი: ${brand.available_brands}`,
    'ფაილს caption-ში შეგიძლია მიუწერო მითითებაც, მაგ.: „აქცენტი გააკეთე ფასდაკლებაზე“.',
  ].join('\n'));
}

// 4) ვიდეო / აუდიო / ხმოვანი
const doc = msg.document;
const docIsMedia = Boolean(doc && /^(audio|video)\//i.test(doc.mime_type || ''));
const media = msg.voice || msg.audio || msg.video || msg.video_note || (docIsMedia ? doc : null);
if (media) {
  const kind = msg.voice ? 'ხმოვანი შეტყობინება'
    : msg.audio ? 'აუდიო'
    : msg.video ? 'ვიდეო'
    : msg.video_note ? 'ვიდეო-რგოლი'
    : /^video/i.test(doc.mime_type) ? 'ვიდეო (ფაილი)' : 'აუდიო (ფაილი)';
  const sizeMb = (media.file_size || 0) / 1048576;
  if (sizeMb > Number(s.max_file_mb || 20)) {
    return fail('too_large', `📦 ფაილი ძალიან დიდია (${sizeMb.toFixed(1)} MB).\nTelegram ბოტს მაქსიმუმ 20 MB ფაილის ჩამოტვირთვა შეუძლია.\nგამოგზავნე უფრო მოკლე ფრაგმენტი, დაბალი ხარისხის ვიდეო ან მხოლოდ აუდიო (mp3/m4a).`);
  }
  const dur = media.duration ? ` (${Math.floor(media.duration / 60)}:${String(media.duration % 60).padStart(2, '0')})` : '';
  Object.assign(out, {
    ok: true,
    type: 'media',
    source_type: kind,
    source_ref: `${kind}${dur}${media.file_name ? ' — ' + media.file_name : ''}`,
    file_id: media.file_id,
    extra_context: raw,
  });
  return [{ json: out }];
}

// 5) ლინკი (თუ ლინკის გარდა ტექსტი მცირეა — ვამუშავებთ როგორც ლინკს)
const urlMatch = raw.match(/https?:\/\/[^\s<>"]+/i);
if (urlMatch) {
  const url = urlMatch[0].replace(/[.,;:!?)\]]+$/, '');
  const rest = raw.replace(urlMatch[0], '').trim();
  if (rest.length < 300) {
    if (/(youtube\.com|youtu\.be|instagram\.com|tiktok\.com|facebook\.com|fb\.watch)/i.test(url)) {
      return fail('unsupported_url', '🔗 ამ პლატფორმის ლინკიდან კონტენტს ვერ ვიღებ (YouTube/Instagram/TikTok/Facebook).\nგადმოწერე ვიდეო და გამომიგზავნე ფაილად (მაქს. 20 MB), ან ჩააკოპირე ტექსტი.');
    }
    Object.assign(out, {
      ok: true,
      type: 'url',
      source_type: 'ლინკი',
      source_ref: url,
      url,
      extra_context: rest,
    });
    return [{ json: out }];
  }
}

// 6) ტექსტი
if (raw.length >= 20) {
  Object.assign(out, {
    ok: true,
    type: 'text',
    source_type: raw.length > 600 ? 'სტატიის ტექსტი' : 'მოკლე შეტყობინება',
    source_ref: raw.slice(0, 120) + (raw.length > 120 ? '…' : ''),
    text: raw,
  });
  return [{ json: out }];
}
if (raw.length > 0) {
  return fail('too_short', '✂️ ტექსტი ძალიან მოკლეა. დაწერე მინიმუმ ერთი-ორი წინადადება: რა გინდა, რომ ვთქვათ, ვისთვის და რატომ.');
}
return fail('unsupported', '🤔 ამ ტიპის შეტყობინებას ვერ ვამუშავებ.\nგამომიგზავნე ტექსტი, ლინკი, ვიდეო, ხმოვანი ან აუდიო ფაილი.\n/help — დახმარება');

// Telegram ხმოვანს `.oga` გაფართოებით ინახავს — gpt-4o-transcribe ამ გაფართოებას არ იღებს,
// თუმცა ფორმატი იგივე ogg/opus-ია. ვარქმევთ `.ogg`-ს; სხვა ფაილებს ვტოვებთ უცვლელად.
const item = $input.first();
const bin = item.binary?.data;
if (!bin) throw new Error('ფაილი ვერ ჩამოიტვირთა (binary data არ არის)');

if (/\.oga$/i.test(bin.fileName || '') || bin.fileExtension === 'oga') {
  bin.fileName = (bin.fileName || 'voice.oga').replace(/\.oga$/i, '.ogg');
  bin.fileExtension = 'ogg';
  bin.mimeType = 'audio/ogg';
}
return [item];

// HTML-დან სტატიის სუფთა ტექსტის ამოღება
const s = $('Settings').first().json;
const d = $('Detect Input').first().json;
const html = String($input.first().json.html || '');

const decode = (t = '') => t
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&laquo;/gi, '«').replace(/&raquo;/gi, '»').replace(/&mdash;/gi, '—').replace(/&ndash;/gi, '–').replace(/&hellip;/gi, '…')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)));

const meta = (name) => {
  const tag = (html.match(new RegExp(`<meta[^>]*(?:property|name)=["']${name}["'][^>]*>`, 'i')) || [''])[0];
  const c = tag.match(/content=(?:"([^"]*)"|'([^']*)')/i);
  return c ? decode(c[1] ?? c[2]).trim() : '';
};

const clean = (h) => decode(h
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|nav|header|footer|aside|form|iframe|button)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|h[1-6]|li|tr|section|blockquote)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t\f\v\r]+/g, ' ')
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.length >= 25) // მენიუს, ღილაკების და სხვა მოკლე ხაზების მოშორება
  .join('\n');

const all = (re) => [...html.matchAll(re)].map(m => m[1]);
const candidates = [
  ...all(/<article\b[^>]*>([\s\S]*?)<\/article>/gi),
  ...all(/<main\b[^>]*>([\s\S]*?)<\/main>/gi),
  ...all(/<body\b[^>]*>([\s\S]*?)<\/body>/gi),
].map(clean);

const body = candidates.find(t => t.length >= 800)
  || candidates.sort((a, b) => b.length - a.length)[0]
  || clean(html);

const titleTag = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
const title = meta('og:title') || decode(titleTag).trim();
const description = meta('og:description') || meta('description');

const text = [
  title && `სათაური: ${title}`,
  description && `აღწერა: ${description}`,
  body,
].filter(Boolean).join('\n\n').slice(0, Number(s.max_source_chars || 12000));

const tooShort = body.length < 200;

return [{
  json: {
    source_type: d.source_type,
    source_ref: d.url,
    source_text: tooShort ? '' : text,
    extra_context: d.extra_context,
    error_message: tooShort
      ? '🌐 ლინკიდან სტატიის ტექსტი ვერ ამოვიღე — საიტი ან JavaScript-ით იტვირთება, ან დაცულია (paywall/ავტორიზაცია).\nჩააკოპირე სტატიის ტექსტი და გამომიგზავნე პირდაპირ.'
      : '',
  },
}];

// OpenAI Chat Completions მოთხოვნის აწყობა: system + user prompt + მკაცრი JSON Schema
const s = $('Settings').first().json;
const b = $('Brand Profiles').first().json;
const src = $input.first().json;

const sourceText = String(src.source_text || '').trim().slice(0, Number(s.max_source_chars || 12000));

// ======================== SYSTEM PROMPT ========================
const systemPrompt = `შენ ხარ მარკეტინგული სააგენტოს გამოცდილი ქართველი კოპირაიტერი და SMM სტრატეგი. შენი ამოცანაა, ერთი წყაროდან (ვიდეოს ან აუდიოს ტრანსკრიპტი, სტატია ან ბრენდის მოკლე შეტყობინება) შექმნა მზა კონტენტ-პაკეტი სოციალური ქსელებისთვის.

# 1. ენა — უმთავრესი მოთხოვნა
- წერე მხოლოდ ბუნებრივ, გამართულ, თანამედროვე ქართულ ენაზე — ისე, როგორც დაწერდა ნიჭიერი ქართველი კოპირაიტერი და არა მთარგმნელობითი პროგრამა.
- ნუ თარგმნი ინგლისურ კონსტრუქციებს სიტყვასიტყვით და ნუ გამოიყენებ კალკებს (მაგ.: „ეს არის ის, რაც გჭირდება“, „მიიღე საუკეთესო გამოცდილება“, „გახადე შენი დღე უკეთესი“).
- დაიცავი გრამატიკა: ბრუნვები, ზმნის პირი და რიცხვი, შეთანხმება. მიმართვის ფორმა (შენ/თქვენ) მთელ პაკეტში ერთნაირი უნდა იყოს.
- პუნქტუაცია: ქართული ბრჭყალები „ასე“, ტირე —. წინადადებები იყოს მოკლე და ცოცხალი.
